import math

def min_eating_speed(piles, h):
    def hours_needed(k):
        return sum(math.ceil(p / k) for p in piles)

    lo, hi = 1, max(piles)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if hours_needed(mid) <= h:
            hi = mid                     # feasible, search for a smaller speed
        else:
            lo = mid + 1                  # infeasible, need a faster speed
    return lo

